func (o *redhatBase) parseInstalledPackagesLine(line string) (*models.Package, *models.SrcPackage, error) {
	switch fields := splitRPMQueryFields(line); len(fields) {
	case 6, 7:
		sp, err := func() (*models.SrcPackage, error) {
			switch fields[5] {
			case "(none)":
				return nil, nil
			default:
				n, v, r, _, _, err := splitFileName(fields[5])
				if err != nil {
					o.warns = append(o.warns, xerrors.Errorf("Failed to parse source rpm file. err: %w", err))
					return nil, nil
				}
				return &models.SrcPackage{
					Name:        n,
					Version:     rpmVersion(fields[1], v, r),
					Arch:        "src",
					BinaryNames: []string{fields[0]},
				}, nil
			}
		}()
		if err != nil {
			return nil, nil, xerrors.Errorf("Failed to parse sourcepkg. err: %w", err)
		}

		return &models.Package{
			Name: fields[0],
			Version: func() string {
				switch fields[1] {
				case "0", "(none)":
					return fields[2]
				default:
					return fmt.Sprintf("%s:%s", fields[1], fields[2])
				}
			}(),
			Release: fields[3],
			Arch:    fields[4],
			ModularityLabel: func() string {
				if len(fields) == 7 && fields[6] != "(none)" {
					return fields[6]
				}
				return ""
			}(),
		}, sp, nil
	default:
		return nil, nil, xerrors.Errorf("Failed to parse package line: %s", line)
	}
}

func (o *redhatBase) parseInstalledPackagesLineFromRepoquery(line string) (*models.Package, *models.SrcPackage, error) {
	switch fields := splitRPMQueryFields(line); len(fields) {
	case 7:
		sp, err := func() (*models.SrcPackage, error) {
			switch fields[5] {
			case "(none)":
				return nil, nil
			default:
				n, v, r, _, _, err := splitFileName(fields[5])
				if err != nil {
					o.warns = append(o.warns, xerrors.Errorf("Failed to parse source rpm file. err: %w", err))
					return nil, nil
				}
				return &models.SrcPackage{
					Name:        n,
					Version:     rpmVersion(fields[1], v, r),
					Arch:        "src",
					BinaryNames: []string{fields[0]},
				}, nil
			}
		}()
		if err != nil {
			return nil, nil, xerrors.Errorf("Failed to parse sourcepkg. err: %w", err)
		}

		return &models.Package{
			Name: fields[0],
			Version: func() string {
				switch fields[1] {
				case "0", "(none)":
					return fields[2]
				default:
					return fmt.Sprintf("%s:%s", fields[1], fields[2])
				}
			}(),
			Release: fields[3],
			Arch:    fields[4],
			Repository: func() string {
				switch repo := strings.TrimPrefix(fields[6], "@"); repo {
				case "installed":
					return "amzn2-core"
				default:
					return repo
				}
			}(),
		}, sp, nil
	default:
		return nil, nil, xerrors.Errorf("Failed to parse package line: %s", line)
	}
}

// splitFileName returns a name, version, release, epoch, arch:
//
//	e.g.
//		foo-1.0-1.i386.rpm => foo, 1.0, 1, i386
//		1:bar-9-123a.ia64.rpm => bar, 9, 123a, 1, ia64
//
// https://github.com/rpm-software-management/yum/blob/043e869b08126c1b24e392f809c9f6871344c60d/rpmUtils/miscutils.py#L301
func splitFileName(filename string) (name, ver, rel, epoch, arch string, err error) {
	const expected = "<name>-<version>-<release>.<arch>.rpm"
	invalid := func() (string, string, string, string, string, error) {
		return "", "", "", "", "", xerrors.Errorf("unexpected file name. expected: %q, actual: %q", expected, filename)
	}
	if !strings.HasSuffix(filename, ".rpm") || strings.ContainsAny(filename, "/\\ \t\r\n") {
		return invalid()
	}
	basename := strings.TrimSuffix(filename, ".rpm")
	if basename == "" {
		return invalid()
	}

	// Some RPM implementations emit source RPMs with a dash before "src"
	// instead of the usual architecture suffix separated by a dot.
	if strings.HasSuffix(basename, "-src") {
		arch = "src"
		basename = strings.TrimSuffix(basename, "-src")
	} else {
		archIndex := strings.LastIndex(basename, ".")
		if archIndex == -1 || archIndex == len(basename)-1 {
			return invalid()
		}
		arch = basename[archIndex+1:]
		basename = basename[:archIndex]
	}
	if arch == "" || strings.ContainsAny(arch, ".-:") {
		return invalid()
	}

	if epochIndex := strings.Index(basename, ":"); epochIndex != -1 {
		epoch = basename[:epochIndex]
		if epoch == "" || strings.Trim(epoch, "0123456789") != "" || strings.Contains(basename[epochIndex+1:], ":") {
			return invalid()
		}
		basename = basename[epochIndex+1:]
	}

	relIndex := strings.LastIndex(basename, "-")
	if relIndex == -1 {
		return invalid()
	}
	rel = basename[relIndex+1:]
	nameAndVersion := basename[:relIndex]
	verIndex := strings.LastIndex(nameAndVersion, "-")
	if verIndex == -1 {
		return invalid()
	}
	name = nameAndVersion[:verIndex]
	ver = nameAndVersion[verIndex+1:]
	if name == "" || ver == "" {
		return invalid()
	}
	return name, ver, rel, epoch, arch, nil
}

// splitRPMQueryFields preserves an empty queryformat value represented by two
// adjacent spaces, while treating tabs and other whitespace as separators.
func splitRPMQueryFields(line string) []string {
	line = strings.TrimSpace(line)
	if line == "" {
		return nil
	}

	fields := make([]string, 0, 7)
	for i := 0; i < len(line); {
		start := i
		for i < len(line) && !isRPMWhitespace(line[i]) {
			i++
		}
		fields = append(fields, line[start:i])

		separatorStart := i
		spaces := 0
		allSpaces := true
		for i < len(line) && isRPMWhitespace(line[i]) {
			if line[i] == ' ' {
				spaces++
			} else {
				allSpaces = false
			}
			i++
		}
		if i < len(line) && allSpaces && spaces > 1 {
			fields = append(fields, "")
		}
		if separatorStart == i {
			break
		}
	}
	return fields
}

func isRPMWhitespace(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\r'
}

